<!-- Generated by svelte-trisql-scaffold for users. Edit freely. -->
<script lang="ts">
	import { goto } from '$app/navigation';
	import { page } from '$app/state';
	import { deleteUser, getUser, updateUser } from '#lib/users.remote.ts';

	const row = $derived(await getUser(page.params.id ?? ''));

	async function remove() {
		if (!row) return;
		await deleteUser(row.id);
		await goto('/users');
	}
</script>

{#if row}
	<h1>user {row.id}</h1>
	<form {...updateUser}>
		<input {...updateUser.fields.id.as('hidden', String(row.id))} />
		<label>email <input {...updateUser.fields.email.as('text')} /></label>
		{#each updateUser.fields.email.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<label>name <input {...updateUser.fields.name.as('text')} /></label>
		{#each updateUser.fields.name.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<label>status
			<select {...updateUser.fields.status.as('select')}>
				{#each ["active","inactive"] as option}<option value={option}>{option}</option>{/each}
			</select>
		</label>
		{#each updateUser.fields.status.issues() as issue}<p class="issue">{issue.message}</p>{/each}
		<button>Save</button>
	</form>
	<button onclick={remove}>Delete</button>
{:else}
	<p>Not found.</p>
{/if}
<p><a href="/users">Back to users</a></p>
